// Build client.js from client-body.js: wrap it in the DSH client module loader.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
const pkgDir = path.resolve(here, '..');
const pkg = JSON.parse(fs.readFileSync(path.join(pkgDir, 'package.json'), 'utf8'));
if (typeof pkg.name !== 'string' || pkg.name === '') throw new Error('package.json has no name');

const body = fs.readFileSync(path.join(pkgDir, 'client-body.js'), 'utf8');
const header =
  '// Session bus · settings page. Generated by scripts/build-client.mjs.\n' +
  'window.__ModuleLoader__.load({\n' +
  '  id: ' + JSON.stringify(pkg.name) + ',\n' +
  '  factory(require) {\n' +
  "    'use strict';\n" +
  "    const React = require('react');\n";
const footer = '  },\n});\n';

const target = path.join(pkgDir, 'client.js');
const output = header + body + footer;
const checkOnly = process.argv.includes('--check');
if (checkOnly) {
  const current = fs.existsSync(target) ? fs.readFileSync(target, 'utf8') : '';
  if (current !== output) {
    console.error('client.js is stale: run `node scripts/build-client.mjs`');
    process.exit(1);
  }
  console.log('client.js is up to date');
  process.exit(0);
}
fs.writeFileSync(target, output, 'utf8');
console.log('wrote client.js');
